-- advance identity sequences past existing data so auto-allocated ids do not collide
SELECT setval(pg_get_serial_sequence('item_effects','ItemEffectID'),
       GREATEST((SELECT COALESCE(MAX("ItemEffectID"),0) FROM item_effects),1));
SELECT setval(pg_get_serial_sequence('item_effect_container','EffectContainerID'),
       GREATEST((SELECT COALESCE(MAX("EffectContainerID"),0) FROM item_effect_container),1));
SELECT setval(pg_get_serial_sequence('item_effect_base','EffectID'),
       GREATEST((SELECT COALESCE(MAX("EffectID"),0) FROM item_effect_base),1));

